package ntk.g1.demo;

import java.io.File;
import java.io.FileInputStream;
import java.io.IOException;
import javax.servlet.http.HttpServletRequest;

/**
 * G1 Demo 2: Candidate alert generated by OpenGrep taint analysis, protected by canonical path + trailing separator check.
 */
public class Demo2ProtectedFalsePositive {

    public FileInputStream readProtectedReport(HttpServletRequest req) throws IOException {
        String reportName = req.getParameter("report");
        File candidate = new File("/srv/reports/", reportName);
        String canonicalTarget = candidate.getCanonicalPath();
        if (!canonicalTarget.startsWith("/srv/reports/")) {
            throw new SecurityException("Path traversal outside /srv/reports/ refused");
        }
        return new FileInputStream(candidate);
    }
}
